boost::filesystem::path home_page_path()
{
    return boost::filesystem::path(resources_dir()) / "jusprin" / "home" / "index.html";
}

wxString home_page_url()
{
    if (const char* dev = std::getenv("JUSPRIN_HOME_DEV_URL"); dev != nullptr && *dev != '\0')
        return wxString::FromUTF8(dev);
    const boost::filesystem::path page = home_page_path();
    if (!boost::filesystem::exists(page))
        return {};
    return wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
}

} // namespace

HomeWebView::HomeWebView(wxWindow* parent, const ShellTheme& theme, MainFrame& frame)
    : wxPanel(parent, wxID_ANY), m_theme(theme), m_live_timer(this), m_poll_timer(this)
{
    Bind(wxEVT_TIMER, &HomeWebView::on_live_tick, this, m_live_timer.GetId());
    Bind(wxEVT_TIMER, &HomeWebView::on_poll_tick, this, m_poll_timer.GetId());
    m_backend = std::make_unique<OrcaHomeBackend>(frame);
    m_host    = std::make_unique<HomeHost>(*m_backend, [this](const std::string& envelope) {
        if (m_webview == nullptr)
            return;
        wxString script = "window.__jusprinBridge && window.__jusprinBridge.deliver(";
        script += wxString::FromUTF8(envelope);
        script += ")";
        WebView::RunScript(m_webview, script);
    });
}

wxString agent_page_url(AgentPageMode mode)
{
    wxString url;
    if (const char* dev = std::getenv("JUSPRIN_AGENT_DEV_URL"); dev != nullptr && *dev != '\0') {
        url = wxString::FromUTF8(dev);
    } else {
        const boost::filesystem::path page = agent_page_path();
        if (!boost::filesystem::exists(page))
            return {};
        url = wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
    }
    if (mode == AgentPageMode::PrinterPanel)
        url += "?panel=printer";
    else if (mode == AgentPageMode::Preferences)
        url += "?panel=preferences";
    else if (mode == AgentPageMode::OrcaImport)
        url += "?panel=orca-import";
    return url;
}

