void AgentHost::request_account()
{
    if (!m_model_source)
        return;
    m_model_source->fetch_account([this](std::optional<json> account) {
        // One that could not be read keeps the last answer; signing out clears it.
        const std::vector<std::string> configured = m_model_source->configured_providers();
        const bool signed_in = std::any_of(configured.begin(), configured.end(), [](const std::string& provider) {
            const ProviderProfile* profile = profile_for(provider);
            return profile != nullptr && profile->account_sign_in;
        });
        if (account)
            m_account = std::move(account);
        else if (!signed_in)
            m_account.reset();
        else
            return;
        send_account();
        send_active_chat_model();
    });
}

void AgentHost::send_account()
{
    if (m_handshake)
        send_envelope(Protocol::kAccount,
                      json{{"account", m_account ? *m_account : json()}, {"chatTitles", usage_chat_titles()}}.dump());
}

void AgentHost::request_account_box()
{
    // Signing in or out asks again, so only the latest request is answered.
    const unsigned request = ++m_account_box_request;
    auto answer = [this, request](std::optional<std::string> html) {
        if (request == m_account_box_request && m_handshake)
            send_envelope(Protocol::kAccountBox, json{{"html", html ? json(*html) : json()}}.dump());
    };
    if (m_model_source)
        m_model_source->fetch_account_box(std::move(answer));
    else
        answer(std::nullopt);
}

