void fetch_account(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                   std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<nlohmann::json>)> done)
{
    auto finished = std::make_shared<std::function<void(std::optional<nlohmann::json>)>>(std::move(done));
    auto http     = Slic3r::Http::get(account_url(profile, endpoint_override));
    http.header("Authorization", "Bearer " + api_key);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.header("Accept", "application/json")
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete([cancelled, finished](std::string body, unsigned status) {
            if (*cancelled)
                return;
            nlohmann::json response = nlohmann::json::parse(body, nullptr, false);
            if (status == 200 && account_reply_readable(response)) {
                (*finished)(std::move(response));
                return;
            }
            // A server that answers but not in the account's shape is one the
            // app cannot read: the same as no answer.
            if (status == 200)
                BOOST_LOG_TRIVIAL(error) << "Account answer is missing the credits or usage the app reads: "
                                         << body.substr(0, 200);
            (*finished)(std::nullopt);
        })
        .on_error([cancelled, finished](std::string, std::string, unsigned) {
            if (!*cancelled)
                (*finished)(std::nullopt);
        })
        .perform();
}

    // For an account provider, the wire format the account's model list last
    // gave this model; empty when it gave none, and for other providers.
    virtual std::string model_format(const std::string& provider, const std::string& model) const
    {
        (void) provider;
        (void) model;
        return {};
    }
    // The signed-in account's credits, plan and usage, later, on the host's
    // thread; nothing when no account is signed in or it could not be read.
    using AccountDone = std::function<void(std::optional<nlohmann::json> account)>;
    virtual void fetch_account(AccountDone done) { done(std::nullopt); }
    // The HTML the JusPrin server puts in the box on Preferences › Account,
    // later, on the host's thread; nothing when it sends none or could not be
    // asked. Asked with the account's token when one is signed in.
    using AccountBoxDone = std::function<void(std::optional<std::string> html)>;
    virtual void fetch_account_box(AccountBoxDone done) { done(std::nullopt); }
    // Deletes the signed-in account on its server, later, on the host's
    // thread: whether the server says it is gone.
    using DeleteAccountDone = std::function<void(bool deleted)>;
    virtual void delete_account(DeleteAccountDone done) { done(false); }

void ShellController::open_filament_help(std::size_t slot, const std::string& preset, const std::string& shown)
{
    if (m_task_open || m_printer_panel == nullptr || m_tabpanel == nullptr)
        return;
    if (!preset_exists(Preset::TYPE_FILAMENT, preset)) {
        show_error(m_frame, wxString::Format(_L("The filament preset \"%s\" was not found."), from_u8(preset)));
        return;
    }
    // Tab no longer reaches Preview from the shell, but OrcaSlicer's Ctrl+R
    // (slice and show the preview) still does.
    m_printer_panel->open_filament(slot, preset, shown,
        m_tabpanel->GetSelectedPageName() == TAB_ID_PREVIEW ? _L("Back to Preview") : _L("Back to Prepare"));
    show_task_panel();
}

void ShellController::show_task_panel()
{
    // Keep the stock page constructed and selected. Hiding its sizer item
    // gives the task chat the workspace without changing Orca's tab indices.
    m_task_open = true;
    m_task_origin_tab = m_tabpanel->GetSelectedPageName();
    m_home->set_live(false);
    m_workspace_sizer->Show(false);
    m_left_pane->Hide();
    m_left_resize_handle->Hide();
    m_status_row->Hide();
    m_agent_pane->Hide();
    m_agent_resize_handle->Hide();
    m_printer_panel->Show();
    m_frame->Layout();
}

void ShellController::restore_task_panel()
{
    if (!m_task_open)
        return;
    m_task_open = false;
    m_task_origin_tab.clear();
    m_printer_panel->Hide();
    m_workspace_sizer->Show(true);
    m_agent_pane->Show(!m_agent_pane_collapsed);
    m_agent_resize_handle->Show(!m_agent_pane_collapsed);
    on_page_changed();
    apply_agent_pane_width();
}

void ShellController::on_page_changed()
{
    if (!m_installed || m_home == nullptr || m_tabpanel == nullptr)
        return;
    if (m_task_open) {
        if (m_tabpanel->GetSelectedPageName() != m_task_origin_tab)
            m_printer_panel->close();
        return;
    }
    const bool home = m_tabpanel->GetSelectedPageName() == TAB_ID_HOME;
    // The project's chats spend the credits Home's account card shows.
    if (home && !m_home_shown)
        m_home->backend().refresh_account();
    if (home)
        m_home->refresh();
    // Coming onto the screen, Home shows its gallery, or the Print history
    // the project asked for on the way.
    if (home && !m_home_shown)
        m_home->show_screen(std::exchange(m_home_screen, nlohmann::json{{"screen", "home"}}));
    m_home_shown = home;
    m_home->set_live(home);
    // Home and the Notebook share the workspace slot, so exactly one is shown.
    // The Notebook is only hidden while Home is the selection: post_init
    // selects the Prepare tab to map the GL canvas before it initialises
    // OpenGL, and this handler runs on that selection, so the Notebook is
    // shown at the moment the canvas has to be on screen.
    // The header belongs to the workspace: its controls act on the open
    // project, so Home, which has no project in front, shows no header.
    m_home->Show(home);
    m_tabpanel->Show(!home);
    m_status_row->Show(!home);
    // The pane lists the project being prepared; Preview draws its own plate
    // picker and Home has no project in front.
    const bool left_pane_available = !home && m_tabpanel->GetSelectedPageName() == TAB_ID_PREPARE;
    if (m_status_row != nullptr)
        m_status_row->set_left_pane_available(left_pane_available);
    const bool show_left_pane = left_pane_available && !m_left_pane_collapsed;
    m_left_pane->Show(show_left_pane);
    m_left_resize_handle->Show(show_left_pane);
    m_frame->Layout();
    apply_left_pane_width();
    set_agent_pane_collapsed(home ? true : m_agent_pane_user_collapsed);
}

